import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.BiXHgXAn.js";const m=JSON.parse('{"title":"Experiments","description":"Guide to Task’s experimental features and how to use them","frontmatter":{"title":"Experiments","description":"Guide to Task’s experimental features and how to use them","section":"Project","docType":"project","outline":"deep"},"headers":[],"relativePath":"docs/experiments/index.md","filePath":"next/docs/experiments/index.md"}'),n={name:"docs/experiments/index.md"};function o(r,e,l,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="experiments" tabindex="-1">Experiments <a class="header-anchor" href="#experiments" aria-label="Permalink to &quot;Experiments&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>All experimental features are subject to breaking changes and/or removal <em>at any time</em>. We strongly recommend that you do not use these features in a production environment. They are intended for testing and feedback only.</p></div><p>In order to allow Task to evolve quickly, we sometimes roll out breaking changes to minor versions behind experimental flags. This allows us to gather feedback on breaking changes before committing to a major release. This process can also be used to gather feedback on important non-breaking features before their design is completed. This document describes the <a href="#workflow">experiment workflow</a> and how you can get involved.</p><p>You can view the full list of active experiments in the sidebar submenu to the left of the page and click on each one to find out more about it.</p><h2 id="enabling-experiments" tabindex="-1">Enabling Experiments <a class="header-anchor" href="#enabling-experiments" aria-label="Permalink to &quot;Enabling Experiments&quot;">​</a></h2><p>Task uses environment variables to detect whether or not an experiment is enabled. All of the experiment variables will begin with the same <code>TASK_X_</code> prefix followed by the name of the experiment. You can find the exact name for each experiment on their respective pages in the sidebar. If the variable is set <code>=1</code> then it will be enabled. Some experiments may have multiple proposals, in which case, you will need to set the variable equal to the number of the proposal that you want to enable (<code>=2</code>, <code>=3</code> etc).</p><p>There are three main ways to set the environment variables for an experiment. Which method you use depends on how you intend to use the experiment:</p><ol><li><p>Prefixing your task commands with the relevant environment variable(s). For example, <code>TASK_X_{FEATURE}=1 task {my-task}</code>. This is intended for one-off invocations of Task to test out experimental features.</p></li><li><p>Adding the relevant environment variable(s) in your &quot;dotfiles&quot; (e.g. <code>.bashrc</code>, <code>.zshrc</code> etc.). This will permanently enable experimental features for your personal environment.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.bashrc</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TASK_X_FEATURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div></li><li><p>Creating a <code>.env</code> or a <code>.taskrc.yml</code> file in the same directory as your root Taskfile.<br> The <code>.env</code> file should contain the relevant environment variable(s), while the <code>.taskrc.yml</code> file should use a YAML format where each experiment is defined as a key with a corresponding value.</p><p>This allows you to enable an experimental feature at a project level. If you commit this file to source control, then other users of your project will also have these experiments enabled.</p><p>If both files are present, the values in the <code>.taskrc.yml</code> file will take precedence.</p></li></ol><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-gmNWr" id="tab-PBFYY5e" checked><label data-title=".taskrc.yml" for="tab-PBFYY5e">.taskrc.yml</label><input type="radio" name="group-gmNWr" id="tab-V_OXBL_"><label data-title=".env" for="tab-V_OXBL_">.env</label></div><div class="blocks"><div class="language-yaml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">experiments</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  FEATURE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TASK_X_FEATURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span></span></code></pre></div></div></div><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><p>Experiments are a way for us to test out new features in Task before committing to them in a major release. Because this concept is built around the idea of feedback from our community, we have built a workflow for the process of introducing these changes. This ensures that experiments are given the attention and time that they need and that we are getting the best possible results out of them.</p><p>The sections below describe the various stages that an experiment must go through from its proposal all the way to being released in a major version of Task.</p><h3 id="_1-proposal" tabindex="-1">1. Proposal <a class="header-anchor" href="#_1-proposal" aria-label="Permalink to &quot;1. Proposal&quot;">​</a></h3><p>All experimental features start with a proposal in the form of a GitHub issue. If the maintainers decide that an issue has enough support and is a breaking change or is complex/controversial enough to require user feedback, then the issue&#39;s experiment status field will be set to <code>proposed</code>. At this point, the issue becomes a proposal and a period of consultation begins. During this period, we request that users provide feedback on the proposal and how it might effect their use of Task. It is up to the discretion of the maintainers to decide how long this period lasts.</p><h3 id="_2-draft" tabindex="-1">2. Draft <a class="header-anchor" href="#_2-draft" aria-label="Permalink to &quot;2. Draft&quot;">​</a></h3><p>Once a proposal&#39;s consultation ends, a contributor may pick up the work and begin the initial implementation. Once a PR is opened, the maintainers will ensure that it meets the requirements for an experimental feature (i.e. flags are in the right format etc) and merge the feature. Once this code is released, the experiment status field will be updated to <code>draft</code>. This indicates that an implementation is now available for use in a release and the experiment is open for feedback.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>During the draft period, major changes to the implementation may be made based on the feedback received from users. There are <em>no stability guarantees</em> and experimental features may be abandoned <em>at any time</em>.</p></div><h3 id="_3-candidate" tabindex="-1">3. Candidate <a class="header-anchor" href="#_3-candidate" aria-label="Permalink to &quot;3. Candidate&quot;">​</a></h3><p>Once an acceptable level of consensus has been reached by the community and feedback/changes are less frequent/significant, the experiment status field will be updated to <code>candidate</code>. This indicates that a proposal is <em>likely</em> to accepted and will enter a period for final comments and minor changes.</p><h3 id="_4-stable" tabindex="-1">4. Stable <a class="header-anchor" href="#_4-stable" aria-label="Permalink to &quot;4. Stable&quot;">​</a></h3><p>Once a suitable amount of time has passed with no changes or feedback, the experiment status field will be updated to <code>stable</code>. At this point, the functionality will be treated like any other feature in Task and any changes <em>must</em> be backward compatible. This allows users to migrate to the new functionality without having to worry about anything breaking in future releases. This provides the best experience for users migrating to a new major version.</p><h3 id="_5-released" tabindex="-1">5. Released <a class="header-anchor" href="#_5-released" aria-label="Permalink to &quot;5. Released&quot;">​</a></h3><p>When an experiment moves to a <code>released</code> status, it becomes the default behavior and flags or config are no longer required to enable the feature. For non-breaking changes, this will happen in a minor release. For breaking changes, this will happen in a major release.</p><h3 id="abandoned-superseded" tabindex="-1">Abandoned / Superseded <a class="header-anchor" href="#abandoned-superseded" aria-label="Permalink to &quot;Abandoned / Superseded&quot;">​</a></h3><p>If an experiment is unsuccessful at any point then the experiment status field will be updated to <code>abandoned</code> or <code>superseded</code> depending on which is more suitable. These experiments will be removed from Task.</p>`,25)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
